    method = struct.pack('>HHHH', access, n_m, d_m, 1)
    method += struct.pack('>HI', n_code, len(body)) + body
    out = struct.pack('>IHH', 0xcafebabe, 0, cf.version) + struct.pack('>H', len(cf.CP) + 1) + b''.join(cf.CP)
