import struct, zlib
import numpy as np

def read_png(fn):
    d = open(fn,'rb').read()
    assert d[:8] == b'\x89PNG\r\n\x1a\n'
    i = 8; idat = b''; w = h = None; depth = ctype = inter = None; plte = None
    while i < len(d):
        ln = struct.unpack('>I', d[i:i+4])[0]; typ = d[i+4:i+8]; body = d[i+8:i+8+ln]; i += 12 + ln
        if typ == b'IHDR':
            w, h, depth, ctype, comp, filt, inter = struct.unpack('>IIBBBBB', body)
        elif typ == b'IDAT':
            idat += body
        elif typ == b'PLTE':
            plte = body
        elif typ == b'IEND':
            break
    raw = zlib.decompress(idat)
    ch = {0:1, 2:3, 3:1, 4:2, 6:4}[ctype]
    assert depth == 8, depth
    assert inter == 0, inter
    stride = w*ch
    arr = np.frombuffer(raw, dtype=np.uint8).reshape(h, stride+1)
    out = np.zeros((h, w, ch), dtype=np.uint16)
    prev = np.zeros(stride, dtype=np.uint16)
    for y in range(h):
        f = arr[y, 0]
        line = arr[y, 1:].astype(np.uint16)
        if f == 0:
            cur = line
        elif f == 1:
            cur = line.copy()
            acc = np.zeros(ch, dtype=np.uint16)
            for x in range(w):
                for c in range(ch):
                    acc[c] = (line[x*ch+c] + acc[c]) & 0xff
                cur[x*ch:(x+1)*ch] = acc
        elif f == 2:
            cur = (line + prev) & 0xff
        elif f == 3:
            cur = line.copy()
            for x in range(w*ch):
                a = cur[x-ch] if x >= ch else 0
                cur[x] = (line[x] + ((a + prev[x]) >> 1)) & 0xff
        elif f == 4:
            cur = line.copy()
            for x in range(w):
                for c in range(ch):
                    idx = x*ch+c
                    a = cur[idx-ch] if x > 0 else 0
                    bb = prev[idx]
                    cc = prev[idx-ch] if x > 0 else 0
                    p = a + bb - cc
                    pa, pb, pc = abs(p-a), abs(p-bb), abs(p-cc)
                    pr = a if (pa <= pb and pa <= pc) else (bb if pb <= pc else cc)
                    cur[idx] = (line[idx] + pr) & 0xff
        else:
            raise Exception('filter %d' % f)
        out[y] = cur.reshape(w, ch)
        prev = cur
    if plte is not None and ctype == 3:
        p = np.frombuffer(plte, dtype=np.uint8).reshape(-1, 3)
        rgb = p[out[:,:,0]]
        return rgb
    if ch >= 3:
        return out[:, :, :3].astype(np.uint8)
    return np.repeat(out[:, :, :1].astype(np.uint8), 3, axis=2)

def map_rows(im, step=1):
    h, w, _ = im.shape
    nw = (im != 255).any(axis=2)
    frac = nw.mean(axis=1)
    return frac

def ascii_map(im, cols=100):
    h, w, _ = im.shape
    lines = []
    for y in range(0, h, 8):
        s = ''
        for x0 in range(0, h and w, max(1, w//cols)):
            block = im[y:y+8, x0:x0+max(1, w//cols)]
            nonwhite = (block != 255).any(axis=2).mean()
            if nonwhite == 0:
                s += '.'
            elif nonwhite < 0.05:
                s += '-'
            elif nonwhite < 0.2:
                s += '+'
            elif nonwhite < 0.6:
                s += '#'
            else:
                s += '@'
        lines.append('%4d %s' % (y, s))
    return '\n'.join(lines)

